from pathlib import Path
import random, math
random.seed(19)
out=Path(__file__).parent/'assets/images'
out.mkdir(parents=True, exist_ok=True)

def save(n,s): (out/n).write_text(s,encoding='utf-8')

def art_base(bg1,bg2,objects,label,pattern=''):
    return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 920 650" role="img" aria-label="Original conceptual scientific artwork: {label}"><defs><linearGradient id="bg" x2="1" y2="1"><stop stop-color="{bg1}"/><stop offset="1" stop-color="{bg2}"/></linearGradient><radialGradient id="orb"><stop stop-color="#d9f7b2" stop-opacity=".45"/><stop offset="1" stop-color="#d9f7b2" stop-opacity="0"/></radialGradient><pattern id="grid" width="54" height="54" patternUnits="userSpaceOnUse"><path d="M 54 0 L 0 0 0 54" fill="none" stroke="#ffffff" opacity=".07"/></pattern></defs><rect width="920" height="650" fill="url(#bg)"/><rect width="920" height="650" fill="url(#grid)"/>{pattern}{objects}<text x="58" y="593" font-family="Arial,sans-serif" font-size="20" font-weight="700" letter-spacing="4" fill="#f4f7ed" opacity=".78">{label.upper()}</text><path d="M58 556H862" stroke="#f2f2eb" opacity=".25"/></svg>'''

