# Omics heatmap and graph
heat='''<g transform="translate(75 106)">'''
colors=['#d4f19b','#90c6a5','#54957c','#e9b980','#204e43','#7ab3aa']
for i in range(8):
 for j in range(12):
  heat+=f'<rect x="{i*32}" y="{j*31}" width="25" height="24" rx="4" fill="{colors[(i*3+j*2+random.randrange(3))%len(colors)]}" opacity=".82"/>'
heat+='</g>'
heat+='''<g fill="none" stroke="#d7ecac" stroke-width="2" opacity=".66"><path d="M395 145L515 92 638 160 764 130 789 293 679 348 541 266 395 145 541 266 615 475 756 507 789 293 679 348 638 160M615 475L679 348 515 92"/></g><g fill="#d4f5aa"><circle cx="395" cy="145" r="11"/><circle cx="515" cy="92" r="14"/><circle cx="638" cy="160" r="8"/><circle cx="764" cy="130" r="9"/><circle cx="789" cy="293" r="14"/><circle cx="679" cy="348" r="19"/><circle cx="541" cy="266" r="11"/><circle cx="615" cy="475" r="15"/><circle cx="756" cy="507" r="9"/></g>'''
